(function() {
  try {
    if (!State.isPaused) { UI.status('Pause (EDIT) to modify world'); return; }
    Engine.setRenderMode(4);
    const prop = World.createObject('cube', 'Mat Stone Crate', 0x8a8680, true);
    prop.position.set(1.2, 0.5, -2);
    prop.userData.surfaceType = 'concrete';
    prop.userData.materialPreset = 'pbr_concrete_weathered';
    if (window.MaterialPresets?.applyMaterialPreset) {
      MaterialPresets.applyMaterialPreset(prop, 'pbr_concrete_weathered');
    }
    // TEXTURE: Mat Stone Crate → textures/mat_stone_crate_albedo.png
    prop.userData.textureHint = 'textures/mat_stone_crate_albedo.png';
    if (window.NegativeLod?.enableObject) {
      NegativeLod.enableObject(prop, { distance: 100, source: 'user' });
    }
    UI.status('Scene extended');
  } catch (e) { console.error(e); UI.status('Error: ' + e.message); }
})();

